def test_mutating_one_input_flips_later_hash(session):
    """Change exactly one recorded input's direction; some later checkpoint
    hash must differ (or vanish because the mutant died earlier)."""
    inputs = [(t, d) for t, d in session["inputs"]]
    all_dirs = ["UP", "DOWN", "LEFT", "RIGHT"]
    baseline = {int(t): h for t, h in session["checkpoints"].items()}

    found_flip = None
    for i, (tick, direction) in enumerate(inputs):
        for alt in all_dirs:
            if alt == direction:
                continue
            mutated = inputs[:i] + [(tick, alt)] + inputs[i + 1 :]
            checkpoints, _, _ = replay(
                seed=session["seed"],
                inputs=mutated,
                total_ticks=session["total_ticks"],
                checkpoint_every=session["checkpoint_every"],
            )
            later = [t for t in baseline if t > tick]
            flipped = [t for t in later if checkpoints.get(t) != baseline[t]]
            if flipped:
                found_flip = (tick, direction, alt, flipped)
                break
        if found_flip:
            break

    assert found_flip is not None, (
        "no single-input mutation flipped any later checkpoint hash"
    )
    mtick, orig, alt, flipped = found_flip
    print(
        f"\nmutation: input at tick {mtick} changed {orig} -> {alt}; "
        f"flipped hashes at ticks {flipped}"
    )

